package com.deepank.careerraft.documents;
import com.deepank.careerraft.domain.Job;import com.deepank.careerraft.intelligence.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class CoverLetterBuilder{private final EvidenceMatcher matcher;private final EvidenceCatalog catalog;public CoverLetterBuilder(EvidenceCatalog c){catalog=c;matcher=new EvidenceMatcher(c);}public CoverLetter build(Job job,List<String>selected){List<String>ids=new ArrayList<>();for(String id:selected)if(catalog.byId().containsKey(id)&&List.of(EvidenceType.EXPERIENCE,EvidenceType.PROJECT).contains(catalog.get(id).type()))ids.add(id);for(var m:matcher.match(job.description(),12))if(catalog.byId().containsKey(m.claimId())&&!ids.contains(m.claimId())&&List.of(EvidenceType.EXPERIENCE,EvidenceType.PROJECT).contains(catalog.get(m.claimId()).type()))ids.add(m.claimId());ids=ids.stream().distinct().limit(3).toList();String company=(job.company()==null||job.company().isBlank())?"your team":job.company();String title=job.title()==null?"Software Engineer":job.title();String reason=job.description().toLowerCase().matches(".*(payments?|banking).*" )?"The opportunity to contribute to reliable products in a business-critical domain particularly appeals to me.":job.description().toLowerCase().matches(".*(scale|distributed|reliable).* ")?"The opportunity to work on dependable software at meaningful scale particularly appeals to me.":"The opportunity to contribute to a team solving meaningful engineering problems particularly appeals to me.";String text="Dear Hiring Team,\n\nI am excited to apply for the "+title+" position at "+company+". I am a backend-focused software engineer with professional experience building and improving services in the Payments domain. "+reason+"\n\nIn my current role, I work on backend services supporting payment workflows, with a focus on reliable delivery, testing, and system improvement. This experience has strengthened my ability to take ownership of a problem, work carefully through its details, and deliver dependable changes in a production environment.\n\nWhat draws me to this opportunity is the chance to contribute through careful engineering, ownership, and practical delivery. Alongside my professional work, I have also built software projects independently, which has helped me develop a habit of learning quickly and turning ideas into working systems.\n\nI would welcome the opportunity to bring this approach to "+company+" as a "+title+". Thank you for taking the time to consider my application.\n\nBest regards,\nDeepank Khera";return new CoverLetter(text,ids);}}
